static Model ModelFor(const std::string& scope){Model m;m.equip=scope;m.part="body";m.relativePath="pl\\f_equip\\"+scope+"\\body\\mod\\f_body"+scope.substr(2);for(int i=0;i<3;i++){auto name="HotkeyMaterial"+std::to_string(i);m.materials.push_back({name,MaterialNameHash(name),i});Mesh mesh;mesh.index=i;mesh.materialId=(uint16_t)i;mesh.vertexCount=(uint16_t)(100+i);mesh.indexCount=300+i*3;mesh.lod=65535;m.meshes.push_back(mesh);}m.signature=MeshOrderSignature(m);return m;}
static uint64_t GroupFor(const Model& m,const std::string& name,int material,bool global=false,bool main=false){auto& d=Get().data;Group g;g.id=d.nextId++;g.scope=m.equip;g.name=name;g.global=global;g.main=main;if(!main)g.members.insert({m.relativePath,m.materials[material].hash,false});Preset hide;hide.id=d.nextId++;hide.name="隐藏";hide.rules.hidden.insert({m.relativePath,(uint32_t)material,true});Preset show;show.id=d.nextId++;show.name="显示";g.presets={hide,show};g.working=show.rules;g.selected=g.defaultPreset=show.id;d.groups.push_back(g);return g.id;}
namespace mock {
std::map<uintptr_t,std::vector<unsigned char>> blocks;
bool Read(uintptr_t a,void* value,size_t n){for(auto& [p,b]:blocks)if(a>=p&&a-p<=b.size()&&n<=b.size()-(a-p)){memcpy(value,b.data()+(a-p),n);return true;}return false;}
void Bytes(uintptr_t a,const void* v,size_t n){auto& b=blocks[a];b.resize(n);memcpy(b.data(),v,n);}
template<class T>void Put(uintptr_t a,T v){Bytes(a,&v,sizeof(v));}
}
